import org.eclipse.swt.graphics.Color;
import org.eclipse.swt.graphics.StyleRange;
import org.eclipse.swt.widgets.Display;
import org.junit.Test;

class AnotherClass {
    private static final int NORMAL = 0;
    // A method in a different class with the same name and old parameter order
    private StyleRange createStyleRange(int start, int end, int foreground, int background, int style) {
        return new StyleRange(start, end - start, null, null, style);
    }
    @Test
    public void testSomething() {
        // Should not match because it's in 'AnotherClass', not 'TextPresentationTest'
        StyleRange range = createStyleRange(0, 2, 1, -1, NORMAL);
    }
}

public class TextPresentationTest {
    private static final int NORMAL = 0;
    private static final int BOLD = 1;

    // This overload has Color arguments, so the 'int-only' rule should not match
    private StyleRange createStyleRange(int start, int end, Color foreground, Color background, int style) {
        return new StyleRange(start, end - start, foreground, background, style);
    }
    private Color createColor(int r, int g, int b) { return null; } // Dummy method
    private Display fDisplay = Display.getDefault(); // Dummy field

    @Test
    public void testMergeStyleRangeColor() {
        Color blue = fDisplay.getSystemColor(0);
        Color red = fDisplay.getSystemColor(1);
        // This call should not match the rule because its arguments are Color objects, not ints,
        // thus it's a different method overload.
        StyleRange range = createStyleRange(0, 2, blue, red, NORMAL);
    }
}
